/* @autogenerated */
import { BulkEditField } from 'app/shared/toolkit/bulk-edit/bulk-edit.model';
import { ObservedIssue } from 'app/features/observe/observed-issue/model/observed-issue.model';
import { BaseBulkEditAction } from 'app/shared/toolkit/action/base-bulk-edit-action';
import { ObservedIssueRepository } from 'app/features/observe/observed-issue/repository/observed-issue-repository.service';
import { BulkEditDialogData } from 'app/shared/toolkit/bulk-edit/bulk-edit-dialog.component';
import { Component, inject } from '@angular/core';

/** Edición masiva de observed issue: los campos que se pueden cambiar en bloque. */
@Component({ selector: 'observed-issue-view-bulk-edit-action', standalone: false, template: '' })
export class ObservedIssueViewBulkEditActionComponent extends BaseBulkEditAction<ObservedIssue> {
  readonly name = 'bulkEdit';
  protected readonly scope = 'observe/observed-issue';
  protected readonly repository = inject(ObservedIssueRepository);

  protected override keyOf(item: ObservedIssue): string {
    return String(item.uid);
  }

  /** Los campos que se pueden editar en bloque y el tipo de cada uno. */
  protected bulkFields(): readonly BulkEditField<ObservedIssue>[] {
    return [
      { name: 'fingerprint', label: this.text('fieldFingerprint'), type: 'text' },
      { name: 'title', label: this.text('fieldTitle'), type: 'text' },
      { name: 'culprit', label: this.text('fieldCulprit'), type: 'text', optional: true },
      {
        name: 'kind',
        label: this.text('fieldKind'),
        type: 'enum',
        options: [
          { value: 'error', label: 'ERROR' },
          { value: 'performance', label: 'PERFORMANCE' },
        ],
      },
      {
        name: 'level',
        label: this.text('fieldLevel'),
        type: 'enum',
        options: [
          { value: 'warning', label: 'warning' },
          { value: 'error', label: 'error' },
          { value: 'fatal', label: 'fatal' },
        ],
      },
    ];
  }

  protected override toDialogData(count: number): BulkEditDialogData<ObservedIssue> {
    return {
      title: this.text('dialogTitle'),
      count,
      singular: this.text('selectedSingular'),
      plural: this.text('selectedPlural'),
      confirm: this.text('confirm'),
      cancel: this.text('cancel'),
      fields: this.bulkFields(),
    };
  }
}
